pub fn normalizeStringNodeT(comptime T: type, str: []const T, buf: []T, comptime platform: Platform) []const T {
        if ((str.len == 0)) {
            buf[cp_cast_int(usize, 0)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(46)) == .int or @typeInfo(@TypeOf(46)) == .comptime_int)) @as(T, @enumFromInt(46)) else @as(T, 46));
            return buf[0..1];
        }
        const is_absolute = platform.isAbsoluteT(T, str);
        const trailing_separator = platform.isSeparatorT(T, str[@as(usize, @intCast((str.len - 1)))]);
        var buf_ = (if ((platform == .windows)) buf else buf[1..]);
        _ = &buf_;
        var out = (if ((!is_absolute)) normalizeStringGenericT(T, str, buf_, true, platform.separator(), platform.getSeparatorFuncT(), false) else normalizeStringGenericT(T, str, buf_, false, platform.separator(), platform.getSeparatorFuncT(), false));
        _ = &out;
        if ((out.len == 0)) {
            if (is_absolute) {
                buf[cp_cast_int(usize, 0)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(platform.separator())) == .int or @typeInfo(@TypeOf(platform.separator())) == .comptime_int)) @as(T, @enumFromInt(platform.separator())) else @as(T, platform.separator()));
                return buf[0..1];
            }
            if (trailing_separator) {
                const sep = platform.trailingSeparator();
                buf[cp_cast_int(usize, 0)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(sep[0])) == .int or @typeInfo(@TypeOf(sep[0])) == .comptime_int)) @as(T, @enumFromInt(sep[0])) else @as(T, sep[0]));
                buf[cp_cast_int(usize, 1)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(sep[1])) == .int or @typeInfo(@TypeOf(sep[1])) == .comptime_int)) @as(T, @enumFromInt(sep[1])) else @as(T, sep[1]));
                return buf[0..2];
            }
            buf[cp_cast_int(usize, 0)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(46)) == .int or @typeInfo(@TypeOf(46)) == .comptime_int)) @as(T, @enumFromInt(46)) else @as(T, 46));
            return buf[0..1];
        }
        if (trailing_separator) {
            if ((!platform.isSeparatorT(T, out[@as(usize, @intCast((out.len - 1)))]))) {
                buf_[cp_cast_int(usize, out.len)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(platform.separator())) == .int or @typeInfo(@TypeOf(platform.separator())) == .comptime_int)) @as(T, @enumFromInt(platform.separator())) else @as(T, platform.separator()));
                out = buf_[0..(out.len + 1)];
            }
        }
        if (is_absolute) {
            if ((platform == .windows)) {
                return out;
            }
            buf[cp_cast_int(usize, 0)] = (if (comptime @typeInfo(T) == .@"enum" and (@typeInfo(@TypeOf(platform.separator())) == .int or @typeInfo(@TypeOf(platform.separator())) == .comptime_int)) @as(T, @enumFromInt(platform.separator())) else @as(T, platform.separator()));
            out = buf[0..(out.len + 1)];
        }
        return out;
}

pub fn basename(path: []const u8) []const u8 {
        if ((path.len == 0)) {
            return "";
        }
        var end_index: usize = (path.len - 1);
        _ = &end_index;
        while (isSepAny(path[@as(usize, @intCast(end_index))])) {
            if ((end_index == 0)) {
                return "/";
            }
            end_index = (end_index - 1);
        }
        var start_index: usize = end_index;
        _ = &start_index;
        end_index = (end_index + 1);
        while ((!isSepAny(path[@as(usize, @intCast(start_index))]))) {
            if ((start_index == 0)) {
                return path[0..end_index];
            }
            start_index = (start_index - 1);
        }
        return path[(start_index + 1)..end_index];
}

pub fn lastIndexOfSep(path: []const u8) ?usize {
        return lastIndexOfSepT(u8, path);
}

pub fn lastIndexOfSepT(comptime T: type, path: []const T) ?usize {
        if (comptime (!bun.Environment.isWindows)) {
            return strings.lastIndexOfCharT(T, path, 47);
        }
        return std.mem.lastIndexOfAny(T, path, "/\\");
}

pub fn nextDirname(path_: []const u8) ?[]const u8 {
        var path = path_;
        _ = &path;
        var root_prefix: []const u8 = "";
        _ = &root_prefix;
        if ((path.len > 3)) {
            if (((path[1] == 58) and isSepAny(path[2]))) {
                root_prefix = @as([]const u8, path[0..3]);
            }
        }
        if ((path.len == 0)) {
            return (if ((root_prefix.len > 0)) root_prefix else null);
        }
        var end_index: usize = (path.len - 1);
        _ = &end_index;
        while (isSepAny(path[@as(usize, @intCast(end_index))])) {
            if ((end_index == 0)) {
                return (if ((root_prefix.len > 0)) root_prefix else null);
            }
            end_index = (end_index - 1);
        }
        while ((!isSepAny(path[@as(usize, @intCast(end_index))]))) {
            if ((end_index == 0)) {
                return (if ((root_prefix.len > 0)) root_prefix else null);
            }
            end_index = (end_index - 1);
        }
        if (((end_index == 0) and isSepAny(path[0]))) {
            return path[0..1];
        }
        if ((end_index == 0)) {
            return (if ((root_prefix.len > 0)) root_prefix else null);
        }
        return path[0..(end_index + 1)];
}

